import { staffRoute } from "@/server/api/handler";
import { exportRequestInput, listExports, requestExport } from "@/server/services/exports";

export const GET = staffRoute({ permission: "reports.export" }, async ({ ctx }) => ({ data: await listExports(ctx) }));

/** Queue a CSV export (generated by the worker; download link valid for 24 hours). */
export const POST = staffRoute({ permission: "reports.export", body: exportRequestInput }, async ({ ctx, body }) => ({ data: await requestExport(ctx, body), status: 202 }));
